INSERT OR IGNORE INTO mission_study_materials (mission_id,title,introduction,explanation,example_code,example_explanation,key_points_json,common_mistakes_json,references_json) VALUES (230,'Iteradores','Antes da batalha, entenda protocolo iterador.','Iteradores é uma etapa essencial para escrever Python legível, previsível e reutilizável.','class Contagem:
    def __init__(self, atual): self.atual = atual
    def __iter__(self): return self
    def __next__(self):
        if self.atual <= 0: raise StopIteration
        valor, self.atual = self.atual, self.atual - 1
        return valor
return list(Contagem(inicio))','Observe o contrato da função, adapte o raciocínio e escreva sua própria solução.','["Domine protocolo iterador","Retorne exatamente o formato pedido","Considere entradas vazias e limites"]','["Alterar a assinatura solicitada","Confundir retorno com print","Ignorar tipos e casos extremos"]','[{"label":"Tutorial oficial do Python","url":"https://docs.python.org/3/tutorial/"}]');
